slides[24]['cards']=[]
# Keep dense official labels readable; substantive details remain in the board.
slides[15]['table']['rows'][2][2]='Partially Fulfilled: صيانة عامة مثبتة؛ إغلاق 27–29 أكتوبر واسم القاعة الرسمي غير مختبرين.'
