slides[4]['title']='سير العمل التقليدي — AS-IS'
slides[5]['title']='سير العمل والتفويض — TO-BE'
for slide in slides:
    # Arabic status labels avoid bidirectional punctuation ambiguity in dense cells.
    for row in (slide.get('table') or {}).get('rows',[]):
        for i,v in enumerate(row):
            row[i]=v.replace('Partially Fulfilled:','متحقق جزئيًا:')
    for c in slide['cards']:
        c['text']=c['text'].replace('Missing:','غير متحقق:')
(OUT/'deck_content.json').write_text(json.dumps(slides,ensure_ascii=False,indent=2),encoding='utf-8')
print(f'{len(slides)} slides prepared')
